INSERT INTO gear_definition (release_id, gear_kind, gear_index, job, difficulty_group, item_level, visibility, sort_group, display_name, description, icon_path) VALUES
    ('evil-hunter-1.411.buildings-v1', 'weapon', 0, 0, 0, 10, 0, 0, 'Junk Sword', 'Sword, worn out from overuse.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-0.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 1, 0, 1, 30, 0, 0, 'Double-Bladed Axe', 'Double sided axe, it''s great for swinging.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-1.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 2, 0, 1, 30, 0, 0, 'Viking Sword', 'Sword used by Vikings for raids.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-2.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 3, 0, 1, 30, 0, 0, 'Battle Axe', 'Axe that was crafted for battle, and battle only!', '/content/releases/evil-hunter-1.411/gear-icons/weapon-3.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 4, 0, 2, 60, 0, 0, 'Burning Sword', 'At first I thought it was a magical sword on fire, but actually it was just a regular sword on fire.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-4.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 5, 0, 2, 60, 0, 0, 'Golden Axe', 'Axe misplaced by a Spirit, if you lie it will disappear.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-5.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 6, 0, 2, 60, 0, 0, 'Fleshrender', 'Specialized sword used to carve flesh, once cut by this sword one will be horribly disfigured.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-6.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 7, 0, 3, 90, 0, 0, 'Mortal Strike', 'The blade of the sword looked sharp enough to behead the enemy in one blow.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 8, 0, 3, 90, 0, 0, 'Blood Craze', 'Axe cursed by the blood of ten thousand people. One who holds this can think of nothing but human meat.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 9, 1, 0, 10, 0, 0, 'Junk Hammer', 'Hammer, worn out from overuse.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-9.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 10, 1, 1, 30, 0, 0, 'Battle Maul', 'Specialized Maul for close combat. Great for striking from above your head.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-10.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 11, 1, 1, 30, 0, 0, 'War Hammer', 'The biggest hammer found used in a battle. This large and heavy hammer is hard to swing', '/content/releases/evil-hunter-1.411/gear-icons/weapon-11.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 12, 1, 1, 30, 0, 0, 'Morning Star', 'Cute weapon in a shape of a star, people who get hit by this will pass out and never wake up.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-12.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 13, 1, 2, 60, 0, 0, 'Sky Guardian', 'Specialized hammer for defense, the huge size of this weapon means it is only useful for protection.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-13.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 14, 1, 2, 60, 0, 0, 'Oversized Bat', 'One swing from this enormous bat will knock anyone out.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-14.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 15, 1, 2, 60, 0, 0, 'Scourge', 'Tyrant Morganstein''s Hammer, the hammer was rumored to drive the possessor into insanity.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-15.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 16, 1, 3, 90, 0, 1, 'Odin''s Hammer', 'Weapon wielded by a god, which can disintegrate any enemy.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 17, 1, 3, 90, 0, 1, 'God''s Fury', 'Hammer filled with fury. Legend has it, when fueled with the power of the light it''ll be even stronger.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 18, 2, 0, 10, 0, 0, 'Junk Bow', 'Bow, worn out from overuse .', '/content/releases/evil-hunter-1.411/gear-icons/weapon-18.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 19, 2, 1, 30, 0, 0, 'Composite Bow', 'Shorter range compared to a long bow, but still packs a punch!', '/content/releases/evil-hunter-1.411/gear-icons/weapon-19.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 20, 2, 1, 30, 0, 0, 'Long Bow', 'With its long length, the bow is very well balanced.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-20.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 21, 2, 1, 30, 0, 0, 'Short Bow', 'With its short length, this bow is perfect for quick shots, however, it lacks in damage.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-21.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 22, 2, 2, 60, 0, 0, 'Demon Hunter''s Bow', 'Specialized bow used to hunt demons, even the strongest demons trembled before it.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-22.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 23, 2, 2, 60, 0, 0, 'Coronki''s Lion Bow', 'Bow used by Master Archer Coronki, it''s believed to create thunder every time he drew the bowstring.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-23.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 24, 2, 2, 60, 0, 0, 'Mist Bow', 'This bow was made to look like fog, to deceive the enemies.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-24.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 25, 2, 3, 90, 0, 1, 'Trinity Bow', 'True masterpiece crafted by Hades. The bow has exceptional ATK, ATK SPD, and Crit Hit.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 26, 2, 3, 90, 0, 1, 'Trueshot Bow', 'Bow crafted with the finest detail, that when an archer fires the shot it never misses. Archer is able to precisely shoot any part of the body they want.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 27, 3, 0, 10, 0, 0, 'Junk Staff', 'Staff worn out from overuse .', '/content/releases/evil-hunter-1.411/gear-icons/weapon-27.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 28, 3, 1, 30, 0, 0, 'Battle Staff', 'Specialized staff for battle, the durability allows the user to swing it during close combat.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-28.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 29, 3, 1, 30, 0, 0, 'Cross Staff', 'Staff in the shape of a cross, also has religious meanings.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-29.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 30, 3, 1, 30, 0, 0, 'Black Staff', 'Staff that has been harden from being soaked with oil', '/content/releases/evil-hunter-1.411/gear-icons/weapon-30.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 31, 3, 2, 60, 0, 0, 'Undead Defier Staff', 'Staff made from silver, it is very effective against the undead.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-31.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 32, 3, 2, 60, 0, 0, 'Frost Staff', 'Chilling air surrounds the user protecting them from enemies.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-32.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 33, 3, 2, 60, 0, 0, 'Matatabi Staff', 'Loved by cats, if they play with it for a while they will easily become excited.', '/content/releases/evil-hunter-1.411/gear-icons/weapon-33.png'),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 34, 3, 3, 90, 0, 1, 'Demonic Staff', 'Grotesque looking weapon, has a cursed aura around it.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 35, 3, 3, 90, 0, 1, 'Archmage''s Grasp', 'Legendary Staff, wielded by the Archmage who ruled the sky.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 36, 0, 3, 190, 999, 999, 'Ultimate Valhalla', 'A legendary sword that instantly sends an enemy to their demise on the battlefield.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 37, 0, 3, 170, 999, 999, 'Valhalla', 'A legendary sword that instantly sends an enemy to their demise on the battlefield.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 38, 1, 3, 190, 999, 999, 'Ultimate Mjolnir', 'Hammer of Thor, the god of thunder, can level a mountain. It is extremely heavy.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 39, 1, 3, 170, 999, 999, 'Mjolnir', 'Hammer of Thor, the god of thunder, can level a mountain. It is extremely heavy.', NULL),
    ('evil-hunter-1.411.buildings-v1', 'weapon', 40, 2, 3, 190, 999, 999, 'Ultimate Vijaya', 'The bow was made by Vishvakarman, the artisan of the heavens, and represents victory.', NULL),
